insert into public.archives (
  code, business_code, category, title, summary, visibility, origin,
  is_mother, is_archived, sequence_number, abbreviation, index_payload,
  new_badge_visible, published_at
)
select
  code, business_code, category, title, summary, visibility, origin,
  is_mother, is_archived,
  case when exists (
    select 1
    from public.archives sequence_conflict
    where sequence_conflict.category = source.category
      and sequence_conflict.sequence_number = source.sequence_number
  ) then null else sequence_number end,
  abbreviation, index_payload,
  new_badge_visible, published_at
from official_static_archives source
where not exists (
  select 1
  from public.archives archive
  where archive.code = source.code
     or archive.business_code = source.business_code
)
on conflict (code) do nothing;

notify pgrst, 'reload schema';
